defmodule Vault.Ledger.CommandResult do
  @moduledoc """
  Result of executing a ledger command.

  `command` — the name of the command that ran;
  `account_id` — the primary account concerned (the source account for transfers);
  `appended` — the list of `%Event{}` records written by the command, ordered
    by ascending `sequence` (never more than two, and zero on any error);
  `state` — the state of the account after the command.
  """

  defstruct command: nil,
            account_id: nil,
            appended: [],
            state: %Vault.Ledger.AccountState{}
end

defmodule Vault.Ledger.Fold do
  @moduledoc """
  A pure, side-effect-free fold of the event log into the current account state.
  """

  alias Vault.Ledger.{AccountState, Event}

  @spec initial(account_id :: String.t()) :: AccountState.t()
  def initial(account_id) when is_binary(account_id), do: %AccountState{account_id: account_id}

  @doc "Fold a single event into state. Rejects in this exact order:\n\n1. account mismatch\n2. version gap\n3. unknown payload member\n"
  @spec apply_event(AccountState.t(), Event.t()) :: {:ok, AccountState.t()} | {:error, any()}
  def apply_event(%AccountState{} = state, %Event{} = event) do
    cond do
      state.account_id != nil and event.account_id != state.account_id ->
        {:error, {:account_mismatch, state.account_id, event.account_id}}

      event.version != state.version + 1 ->
        {:error, {:version_gap, state.version + 1, event.version}}

      true ->
        apply_payload(state, event.payload, event.version, event.recorded_at)
    end
  end

  @doc "Fold a list of events into state. Returns the starting state for an empty\nlist, stops at the first failure, and rejects (out-of-order) unsorted input.\n"
  @spec replay(AccountState.t(), [Event.t()]) :: {:ok, AccountState.t()} | {:error, any()}
  def replay(state, []), do: {:ok, state}

  def replay(state, events) when is_list(events) do
    with {:ok, _ordered} <- check_order(events), do: fold(state, events)
  end

  defp check_order(events) do
    events
    |> Enum.chunk_every(2, 1, :discard)
    |> Enum.with_index()
    |> Enum.reduce_while({:ok, true}, fn {[curr, next], index}, {_, _} ->
      if next.sequence > curr.sequence do
        {:cont, {:ok, true}}
      else
        {:halt, {:error, {:out_of_order, index + 1}}}
      end
    end)
  end

  defp fold(state, []), do: {:ok, state}
  defp fold(state, [event | rest]) do
    case apply_event(state, event) do
      {:ok, next_state} -> fold(next_state, rest)
      {:error, reason} -> {:error, reason}
    end
  end

  defp apply_payload(state, union, version, recorded_at) when is_struct(union, Ash.Union) do
    case union.type do
      :account_opened ->
        value = union.value

        if state.status == :absent do
          {:ok,
           %AccountState{
             state
             | account_id: state.account_id,
               owner: value.owner,
               balance_cents: value.opening_balance_cents,
               status: :open,
               version: version,
               last_event_type: :account_opened,
               last_recorded_at: recorded_at
           }}
        else
          {:error, :already_open}
        end

      :deposited ->
        case state.status do
          :open ->
            {:ok,
             %AccountState{
               state
               | balance_cents: state.balance_cents + union.value.amount_cents,
                 deposit_count: state.deposit_count + 1,
                 version: version,
                 last_event_type: :deposited,
                 last_recorded_at: recorded_at
             }}

          :absent ->
            {:error, :account_absent}

          :frozen ->
            {:error, :account_frozen}
        end

      :withdrawn ->
        case state.status do
          :open ->
            new_balance = state.balance_cents - union.value.amount_cents

            if new_balance >= 0 do
              {:ok,
               %AccountState{
                 state
                 | balance_cents: new_balance,
                   withdrawal_count: state.withdrawal_count + 1,
                   version: version,
                   last_event_type: :withdrawn,
                   last_recorded_at: recorded_at
               }}
            else
              {:error, :insufficient_funds}
            end

          :absent ->
            {:error, :account_absent}

          :frozen ->
            {:error, :account_frozen}
        end

      :frozen ->
        if state.status == :open do
          {:ok,
           %AccountState{
             state
             | status: :frozen,
               version: version,
               last_event_type: :frozen,
               last_recorded_at: recorded_at
           }}
        else
          {:error, :not_open}
        end

      :unfrozen ->
        if state.status == :frozen do
          {:ok,
           %AccountState{
             state
             | status: :open,
               version: version,
               last_event_type: :unfrozen,
               last_recorded_at: recorded_at
           }}
        else
          {:error, :not_frozen}
        end

      _other ->
        {:error, {:unknown_event_type, union.type}}
    end
  end

  defp apply_payload(_, _, _, _), do: {:error, :unknown_event_type}
end

defmodule Vault.Ledger.Payload do
  @moduledoc """
  A typed event body: an Ash union type whose members match the five event types.
  On input it consumes a map keyed by a string `"type"`; once stored it is read back
  as an `%Ash.Union{}` with the member atom and the embedded struct value.
  """
  use Ash.Type.NewType,
    subtype_of: :union,
    constraints: [
      types: [
        account_opened: Vault.Ledger.Payloads.AccountOpened,
        deposited: Vault.Ledger.Payloads.Deposited,
        withdrawn: Vault.Ledger.Payloads.Withdrawn,
        frozen: Vault.Ledger.Payloads.Frozen,
        unfrozen: Vault.Ledger.Payloads.Unfrozen
      ]
    ]

  @type_map %{
              "account_opened" => :account_opened,
              "deposited" => :deposited,
              "withdrawn" => :withdrawn,
              "frozen" => :frozen,
              "unfrozen" => :unfrozen
            }

  @doc "Cast an arbitrary map (e.g. `%{\"type\" => \"deposited\"}`) to the payload union."
  @impl true
  def cast_input(map, _) when is_map(map) do
    member = Map.get(map, "type")

    case Map.fetch(@type_map, member) do
      {:ok, m} ->
        value = Map.delete(map, "type")
        {:ok, %Ash.Union{type: m, value: value}}

      :error ->
        :error
    end
  end

  def cast_input(_, _), do: :error

  @impl true
  def cast_stored(%Ash.Union{} = union, _), do: {:ok, union}

  @impl true
  def dump_to_native(%Ash.Union{} = union, _, _), do: {:ok, union}
end

